import{cpus as t}from"node:os";import{round as o}from"../../math/round.js";import{sleep as e}from"../../misc/sleep.js";export async function getCpuUsage(t=100,i=1){if(t<=0)return 0;const n=r();await e(t);const s=r(),a=s.total-n.total,m=s.idle-n.idle;return a<=0?0:o(Math.max(a-m,0)/a*100,i)}function r(){let o=0,e=0;for(const r of t()){for(const t of Object.values(r.times))o+=t;e+=r.times.idle}return{total:o,idle:e}}